:root {
  --cream: #f2e8d5;
  --parchment: #e8d9bc;
  --border-brown: #8b6340;
  --dark-brown: #4a2e0e;
  --rust: #a84b1f;
  --gold: #c9922a;
  --muted-text: #7a5c3a;
  --stamp-red: #8b2020;
  --stamp-red-bg: #f5dada;
  --white: #ffffff;
}

.certificate {
  background-color: var(--cream);
  border: 3px solid var(--border-brown);
  outline: 1px solid var(--gold);
  outline-offset: -6px;
  border-radius: 4px;
  width: 460px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cert-header {
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 2px solid var(--gold);
  padding-bottom: 8px;
}

.cert-emblem {
  font-size: 26px;
  color: var(--rust);
  line-height: 1;
  flex-shrink: 0;
}

.cert-title-group {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.cert-org {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-text);
  text-transform: uppercase;
  margin: 0;
}

.cert-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--dark-brown);
  margin: 0;
  line-height: 1.1;
}

.cert-serial {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
}

.serial-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-text);
  text-transform: uppercase;
}

.serial-num {
  font-size: 13px;
  font-weight: 700;
  color: var(--rust);
  letter-spacing: 0.05em;
}

.cert-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pilot-block {
  background-color: var(--parchment);
  border: 1px solid var(--border-brown);
  border-radius: 3px;
  padding: 5px 10px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.pilot-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--dark-brown);
}

.details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
}

.detail-item {
  background-color: var(--white);
  border: 1px solid var(--parchment);
  border-radius: 3px;
  padding: 4px 8px;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.field-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted-text);
}

.field-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--dark-brown);
}

.cert-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 2px solid var(--gold);
  padding-top: 8px;
  gap: 10px;
}

.footer-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex: 1;
}

.sig-line {
  width: 100%;
  height: 1px;
  background-color: var(--border-brown);
}

.sig-label {
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted-text);
}

.cert-stamp {
  border: 2px solid var(--stamp-red);
  border-radius: 50%;
  width: 66px;
  height: 66px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--stamp-red-bg);
  transform: rotate(-8deg);
}

.stamp-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.stamp-top {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--stamp-red);
  text-transform: uppercase;
}

.stamp-date {
  font-size: 9px;
  font-weight: 700;
  color: var(--stamp-red);
  letter-spacing: 0.04em;
}

.stamp-bottom {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--stamp-red);
  text-transform: uppercase;
}
